// Шлюз «Нужен человек?» из схемы TO-BE — проверяется кодом ДО нейросети.
// Явная просьба оператора и резкий негатив не должны зависеть от решения модели.
const item = $input.first().json;
const text = (item.chatInput || '').toLowerCase();

const askHuman = /(позов|соедин|переключ|нужен|нужна|хочу|дайте|свяжите).{0,25}(оператор|человек|сотрудник|менеджер|специалист)|жив(ой|ого|ому|ым) (человек|оператор|сотрудник)|^\s*оператор/.test(text);
const negative = /!!!|отвратительн|ужасн|издева|безобраз|кошмар|позор|напишу жалобу/.test(text);

return [{ json: {
  ...item,
  needs_human: askHuman || negative,
  reason: askHuman ? 'просьба клиента' : (negative ? 'негатив' : null),
  sentiment: negative ? 'негатив' : 'нейтральная'
} }];

function makeEscalation(reason, sentiment, summary) {
  const now = new Date();
  const hour = Number(new Intl.DateTimeFormat('ru-RU', { timeZone: 'Europe/Moscow', hour: '2-digit', hourCycle: 'h23' }).format(now));
  const workingHours = hour >= 9 && hour < 21;
  const card = {
    card_id: 'CARD-' + now.getTime(),
    created_at: now.toISOString(),
    queue: 'Оператор 1-й линии',
    reason, sentiment, summary,
    received_in_working_hours: workingHours
  };
  const output = workingHours
    ? 'Передаю ваше обращение специалисту. Он увидит всю переписку, повторять вопрос не нужно. Ответ придёт в ближайшее время.'
    : 'Сейчас специалисты не работают. Ваше обращение сохранено, специалист ответит после 9:00 по московскому времени. Повторять вопрос не нужно.';
  return { output, card };
}

// Эскалация без участия нейросети: карточка + ответ клиенту.
const item = $input.first().json;
const result = makeEscalation(item.reason, item.sentiment, 'Клиент написал: «' + item.chatInput + '»');
return [{ json: { ...result, escalated_by: 'правило до агента' } }];

function makeEscalation(reason, sentiment, summary) {
  const now = new Date();
  const hour = Number(new Intl.DateTimeFormat('ru-RU', { timeZone: 'Europe/Moscow', hour: '2-digit', hourCycle: 'h23' }).format(now));
  const workingHours = hour >= 9 && hour < 21;
  const card = {
    card_id: 'CARD-' + now.getTime(),
    created_at: now.toISOString(),
    queue: 'Оператор 1-й линии',
    reason, sentiment, summary,
    received_in_working_hours: workingHours
  };
  const output = workingHours
    ? 'Передаю ваше обращение специалисту. Он увидит всю переписку, повторять вопрос не нужно. Ответ придёт в ближайшее время.'
    : 'Сейчас специалисты не работают. Ваше обращение сохранено, специалист ответит после 9:00 по московскому времени. Повторять вопрос не нужно.';
  return { output, card };
}

// Guardrail после агента: агент НАПИСАЛ, что передаёт обращение человеку,
// но НЕ вызвал инструмент — тогда карточку создаёт код, а не остаётся пустое обещание.
const item = $input.first().json;
const answer = item.output || '';
const steps = JSON.stringify(item.intermediateSteps || []);
const toolCalled = steps.includes('escalate_to_human') || steps.includes('create_return_request');

const claimsHandoff = /(переда(ю|м|ём|ла|л)|передач[уа]|подключ(у|ит|им|аю))/i.test(answer)
  && /(специалист|оператор|сотрудник|человек)/i.test(answer);

if (claimsHandoff && !toolCalled) {
  const chatInput = $('Чат с клиентом').first().json.chatInput || '';
  const result = makeEscalation('сбой системы', 'нейтральная', 'Агент пообещал передачу без вызова инструмента. Сообщение клиента: «' + chatInput + '»');
  return [{ json: { ...result, escalated_by: 'guardrail после агента' } }];
}
return [{ json: { output: answer, escalated_by: toolCalled ? 'инструмент агента' : null } }];
